  ('fbdc9fac-5de7-58a8-9b0d-8ffb6ac54479', 'A', 'Elle fait suite à la veine marginale médiale.', false, null),
  ('fbdc9fac-5de7-58a8-9b0d-8ffb6ac54479', 'B', 'Elle se continue par la veine iliaque externe.', false, null),
  ('fbdc9fac-5de7-58a8-9b0d-8ffb6ac54479', 'C', 'Elle chemine accompagnée par le nerf sural médial.', false, null),
