  ('cadfe08f-47b2-5894-b36a-510a79f93a12', 'E', 'Le nerf du muscle obturateur externe.', false, 'Faux : il est innervé par le nerf obturateur.'),
  ('98007723-639e-51e0-847d-41e3b9ac6ee7', 'A', 'De la partie supérieure de la face médiale de la cuisse.', false, 'Faux : elle dépend de l''obturateur.'),
  ('98007723-639e-51e0-847d-41e3b9ac6ee7', 'B', 'L''articulation du genou.', true, 'Vrai : par ses rameaux articulaires.'),
  ('98007723-639e-51e0-847d-41e3b9ac6ee7', 'C', 'Du muscle sartorius.', false, 'Faux : nerf fémoral.'),
  ('98007723-639e-51e0-847d-41e3b9ac6ee7', 'D', 'Des muscles grand et court adducteurs.', false, 'Faux : le court adducteur dépend de l''obturateur.'),
  ('98007723-639e-51e0-847d-41e3b9ac6ee7', 'E', 'Du muscle pectiné.', false, 'Faux : nerf fémoral.'),
