  ('b75d95aa-8056-57d0-8bd3-47c3cc9a4659', 'B', 'La veine fémorale.', false, 'Présente : en arrière de l''artère.'),
  ('b75d95aa-8056-57d0-8bd3-47c3cc9a4659', 'C', 'La grande veine saphène', true, 'Réponse attendue : veine superficielle, hors du canal.'),
