  ('352300a6-ac5c-5d92-93b9-de7015c67d77', 'B', 'Au canal fémoral avec les vaisseaux fémoraux.', false, null),
  ('352300a6-ac5c-5d92-93b9-de7015c67d77', 'C', 'Au nerf fémoral dans le canal fémoral.', false, null),
