  ('352300a6-ac5c-5d92-93b9-de7015c67d77', 'E', 'Toutes ces propositions sont fausses.', false, null),
  ('df434c0c-bac5-5f8a-a2a3-4ccfb0d4f5e1', 'A', 'Au muscle semi-membraneux et semi-tendineux.', false, null),
