  ('f78eeff2-79d9-53b9-9d83-68d053c722d7', 'B', 'Liquide riche en eaux.', true, 'Vrai : environ 90 % d''eau.'),
  ('f78eeff2-79d9-53b9-9d83-68d053c722d7', 'C', 'est obtenu au sang prélevé avec anti coagulant.', false, 'Faux : avec anticoagulant, on obtient du plasma.'),
  ('f78eeff2-79d9-53b9-9d83-68d053c722d7', 'D', 'Est obtenu du sang prélevé sans anti coagulant.', true, 'Vrai : on laisse le sang coaguler.'),
  ('f78eeff2-79d9-53b9-9d83-68d053c722d7', 'E', 'comporte tous s les nutriments sauf les hormones.', false, 'Faux : il contient aussi les hormones.'),
