  ('4ba6b4a1-8ebf-58bd-ade5-e445ceac2b1a', 'B', 'Assure le transport des gaz', true, 'Vrai : transport des gaz.'),
  ('4ba6b4a1-8ebf-58bd-ade5-e445ceac2b1a', 'C', 'Comportant des cellules fixes et des cellules mobiles', false, 'Faux : toutes ses cellules circulent.'),
  ('4ba6b4a1-8ebf-58bd-ade5-e445ceac2b1a', 'D', 'Est un tissu conjonctif spécialisé de soutient', false, 'Faux : il ne joue pas de rôle de soutien.'),
  ('9d40dbd7-51d5-57cb-9975-e312f9fd8837', 'A', 'Comporte une matrice riche en fibres', false, 'Faux : pas de fibres.'),
  ('9d40dbd7-51d5-57cb-9975-e312f9fd8837', 'B', 'Assure le transport des gazs', true, 'Vrai : transport des gaz.'),
  ('9d40dbd7-51d5-57cb-9975-e312f9fd8837', 'C', 'Comportant des cellules fixes et des cellules mobiles', false, 'Faux : toutes circulent.'),
  ('9d40dbd7-51d5-57cb-9975-e312f9fd8837', 'D', 'Est un tissu conjonctif spécialisé', true, 'Vrai : tissu conjonctif spécialisé.'),
  ('9d40dbd7-51d5-57cb-9975-e312f9fd8837', 'E', 'Ses cellules proviennent de la moelle osseuse', true, 'Vrai : moelle osseuse.'),
